// Grey skeleton bar (§1.15).
export function Bar({ width, height = 11 }: { width: `${number}%` | number; height?: number }) {
  const c = useColors();
  return <View style={{ width, height, borderRadius: 3, backgroundColor: c.soft }} />;
}

// A skeleton row: the shape a list row will take, while it loads (§1.15).
export function SkeletonRow({ lines = 2 }: { lines?: number }) {
  return (
    <Row>
      <Bar width="46%" height={13} />
      {Array.from({ length: lines }, (_, i) => (
        <Bar key={i} width={i === lines - 1 ? '62%' : '88%'} />
      ))}
    </Row>
  );
}

// The three states every data screen has, in one place: loading, failed (with retry), empty.
export function StateRow({
  state,
  message,
  onRetry,
}: {
  state: 'loading' | 'error' | 'empty';
  message?: string;
  onRetry?: () => void;
}) {
  const c = useColors();
  const t = useT();
  return (
    <Row style={{ alignItems: 'center', paddingVertical: 28 }}>
      {state === 'loading' ? <ActivityIndicator color={c.gold} /> : null}
      <AppText variant="meta" style={{ textAlign: 'center' }} color={state === 'error' ? c.dangerText : c.muted}>
        {message ?? t(state === 'loading' ? 'common.loading' : state === 'error' ? 'common.error' : 'common.empty')}
      </AppText>
      {state === 'error' && onRetry ? <SecondaryButton label={t('common.retry')} onPress={onRetry} /> : null}
    </Row>
  );
}

